#!/bin/sh
# Generates the guest-side scenario table from tools/scenarios.json.
#
# The JSON manifest is the source of truth. The guest has no JSON parser (and
# no jq), so this host-side generator turns each scenario into shell variables
# and a check function. The generated file is committed and verified by
# tools/test-scenarios.sh; rerun this script after editing the manifest.
#
# Usage: tools/scenarios-generate.sh [manifest] > tools/scenarios.sh
set -eu

ROOT=$(cd "$(dirname "$0")/.." && pwd)
MANIFEST=${1:-"$ROOT/tools/scenarios.json"}

[ -r "$MANIFEST" ] || {
    echo "scenarios-generate: manifest not readable: $MANIFEST" >&2
    exit 1
}
command -v jq >/dev/null 2>&1 || {
    echo "scenarios-generate: jq is required to read $MANIFEST" >&2
    exit 1
}

if ! jq -e '.schema == "rand-fast/scenarios/v1" and (.scenarios | length > 0)' "$MANIFEST" >/dev/null; then
    echo "scenarios-generate: unsupported manifest schema or no scenarios" >&2
    exit 1
fi

jq -r '
    def q: @sh;
    def us: "\u001f";
    def argv: map(gsub(us; "")) | join(us);
    def expected: ((.expect.top1 // []) + (.expect.contains_any // []))
        | map(gsub(us; "")) | join(us);
    def checks:
        (if .expect.measured then
            (.expect.measured | to_entries[]
                | if .value.min != null then "    measured_min \(.key) \(.value.min)" else empty end,
                  if .value.max != null then "    measured_max \(.key) \(.value.max)" else empty end)
         else empty end),
        (if .expect.top1 then "    top1_any \((.expect.top1 | map(q) | join(" ")))" else empty end),
        (if .expect.contains_any then "    contains_any \((.expect.contains_any | map(q) | join(" ")))" else empty end),
        (if .expect.exclude then "    exclude_causes \((.expect.exclude | map(q) | join(" ")))" else empty end),
        (if .expect.report_p95_min_us then "    report_p95_min \(.expect.report_p95_min_us)" else empty end),
        "    report_ops_min 1";

    "#!/bin/sh",
    "# Generated from tools/scenarios.json by tools/scenarios-generate.sh.",
    "# Edit the manifest and rerun the generator; do not edit this file.",
    "# schema: \(.schema)",
    "SCENARIO_COUNT=\(.scenarios | length)",
    "",
    (.scenarios | to_entries[] | .key as $i | .value |
        "scenario_tag_\($i)=\(.name | q)",
        "scenario_kind_\($i)=\(.kind | q)",
        "scenario_duration_\($i)=\(.duration_s | tostring | q)",
        "scenario_prereqs_\($i)=\((.prerequisites // []) | join(" ") | q)",
        "scenario_fixture_\($i)=\(.fixture | argv | q)",
        "scenario_measured_\($i)=\((.expect.measured // {}) | keys | join(" ") | q)",
        "scenario_expected_\($i)=\(expected | q)",
        "scenario_bg_\($i)_count=\((.background // []) | length)",
        ((.background // []) | to_entries[]
            | "scenario_bg_\($i)_\(.key)=\(.value | argv | q)"),
        "scenario_check_\($i)() {",
        checks,
        "}",
        "")
' "$MANIFEST"
